import { describeBranches, type JsonSchemaOrBoolean } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { parseArrayJsonSchema } from "./array.ts"
import { parseCommonJsonSchema } from "./common.ts"
import {
	parseAnyOfJsonSchema,
	parseCompositionJsonSchema
} from "./composition.ts"
import {
	writeJsonSchemaInsufficientKeysMessage,
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedTypeMessage
} from "./errors.ts"
import { parseNumberJsonSchema } from "./number.ts"
import { parseObjectJsonSchema } from "./object.ts"
import { JsonSchemaScope } from "./scope.ts"
import { parseStringJsonSchema } from "./string.ts"

export type JsonSchemaParseContext = {
	defs: Record<string, JsonSchemaOrBoolean>
	cache: Map<string, Type>
	inProgress: Set<string>
	wrappers: Map<string, Type>
}

const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
]

const hasObjectKeywords = (jsonSchema: object): boolean =>
	objectKeywords.some(key => key in jsonSchema)

const extractDefs = (
	jsonSchema: JsonSchemaOrBoolean
): Record<string, JsonSchemaOrBoolean> =>
	typeof jsonSchema === "object" && jsonSchema !== null && !Array.isArray(jsonSchema) &&
	"$defs" in jsonSchema && jsonSchema.$defs !== undefined ?
		jsonSchema.$defs as Record<string, JsonSchemaOrBoolean>
	:	{}

const createJsonSchemaParseContext = (
	jsonSchema: JsonSchemaOrBoolean
): JsonSchemaParseContext => ({
	defs: extractDefs(jsonSchema),
	cache: new Map(),
	inProgress: new Set(),
	wrappers: new Map()
})

const resolveDef = (name: string, ctx: JsonSchemaParseContext): Type => {
	const cached = ctx.cache.get(name)
	if (cached !== undefined) return cached

	if (!(name in ctx.defs))
		throwParseError(writeJsonSchemaUnresolvableRefMessage(`#/$defs/${name}`))

	ctx.inProgress.add(name)
	try {
		const resolved = parseJsonSchema(ctx.defs[name], ctx)
		ctx.cache.set(name, resolved)
		return resolved
	} finally {
		ctx.inProgress.delete(name)
	}
}

const resolveRef = (name: string, ctx: JsonSchemaParseContext): Type => {
	const cached = ctx.cache.get(name)
	if (cached !== undefined) return cached

	if (!(name in ctx.defs))
		throwParseError(writeJsonSchemaUnresolvableRefMessage(`#/$defs/${name}`))

	// If the referenced definition is not currently being resolved, resolve it
	// eagerly so that the returned type is the actual definition rather than a
	// wrapper (this prevents anyOf/allOf composition from short-circuiting or
	// double-wrapping resolved references).
	if (!ctx.inProgress.has(name)) return resolveDef(name, ctx)

	// Otherwise, we're in the middle of resolving a recursive definition.
	// Return a lazily-resolving wrapper that delegates to the fully-resolved
	// definition once it has been cached.
	let wrapper = ctx.wrappers.get(name)
	if (wrapper === undefined) {
		wrapper = type.unknown.narrow((data, traversalCtx) => {
			const resolved = resolveDef(name, ctx)
			return resolved.allows(data) ?
				true
				:	traversalCtx.reject({
						expected: `valid according to $defs.${name}`,
						actual: printable(data)
					})
		})
		ctx.wrappers.set(name, wrapper)
	}
	return wrapper
}

export const parseRefJsonSchema = (
	ref: string,
	ctx: JsonSchemaParseContext
): Type => {
	const match = /^#\/\$defs\/([^/]+)$/.exec(ref)
	if (match === null) throwParseError(writeJsonSchemaInvalidRefMessage())

	const name = match[1]
	if (!(name in ctx.defs))
		throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))

	return resolveRef(name, ctx)
}

const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaParseContext
): Type | undefined => {
	if (!("if" in jsonSchema)) return undefined

	const ifSchema = jsonSchema.if
	if (ifSchema === undefined) return undefined

	const thenSchema = "then" in jsonSchema ? jsonSchema.then : undefined
	const elseSchema = "else" in jsonSchema ? jsonSchema.else : undefined

	// `if` alone (or `if` with neither `then` nor `else`) imposes no constraints.
	if (thenSchema === undefined && elseSchema === undefined) return undefined

	const ifValidator = parseJsonSchema(ifSchema, ctx)
	const thenValidator =
		thenSchema === undefined ? undefined : parseJsonSchema(thenSchema, ctx)
	const elseValidator =
		elseSchema === undefined ? undefined : parseJsonSchema(elseSchema, ctx)

	const jsonSchemaConditionalValidator = (data: unknown, traversalCtx: any) => {
		if (ifValidator.allows(data)) {
			if (thenValidator === undefined) return true
			return thenValidator.allows(data) ?
				true
				:	traversalCtx.reject({
						expected: `valid according to 'then' schema ${thenValidator.description}`,
						actual: printable(data)
					})
