import {
	describeBranches,
	rootSchema,
	type Intersection,
	type Predicate,
	type Traversal
} from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type, type JsonSchema, type Out, type Type } from "arktype"
import {
	writeJsonSchemaArrayAdditionalItemsAndItemsAndPrefixItemsMessage,
	writeJsonSchemaArrayNonArrayItemsAndAdditionalItemsMessage
} from "./errors.ts"
import { parseJsonSchema, type JsonSchemaParseContext } from "./json.ts"
import { JsonSchemaScope } from "./scope.ts"

const deepNormalize = (data: unknown): unknown =>
	typeof data === "object" ?
		data === null ? null
		: Array.isArray(data) ? data.map(item => deepNormalize(item))
		: Object.fromEntries(
				Object.entries(data)
					.map(([k, v]) => [k, deepNormalize(v)] as const)
					.sort((l, r) => (l[0] > r[0] ? 1 : -1))
			)
	:	data

const jsonSchemaArrayUniqueItemsValidator = (
	array: readonly unknown[],
	ctx: Traversal
) => {
	const seen: Record<string, true> = {}
	const duplicates: unknown[] = []
	for (const item of array) {
		const stringified = JSON.stringify(deepNormalize(item))
		if (stringified in seen) duplicates.push(item)
		else seen[stringified] = true
	}
	return duplicates.length === 0 ?
			true
		:	ctx.reject({
				expected: "an array of unique items",
				actual: `an array with ${duplicates.length} duplicates: ${describeBranches(
					duplicates.map(duplicate => printable(duplicate)),
					{ finalDelimiter: ", and " }
				)}`
			})
}

const arrayContainsItemMatchingSchema = (schema: Type) => {
	const jsonSchemaArrayContainsValidator = (
		array: readonly unknown[],
		ctx: Traversal
	) =>
		array.some(item => schema.allows(item)) === true ?
			true
		:	ctx.reject({
				expected: `at least one item satisfying 'contains' schema of ${schema.description}`,
				actual: printable(array)
			})

	return jsonSchemaArrayContainsValidator
}

export const parseArrayJsonSchema = (
	jsonSchema: JsonSchema.Array,
	ctx: JsonSchemaParseContext
): Type<unknown[]> => {
	const validatedSchema = JsonSchemaScope.ArraySchema.assert(jsonSchema) as JsonSchema.Array

	const arktypeArraySchema: Intersection.Schema<Array<unknown>> = {
		proto: "Array"
	}

	let itemsIsPrefixItems = false
	if ("prefixItems" in validatedSchema) {
		if ("items" in validatedSchema) {
			if ("additionalItems" in validatedSchema) {
				throwParseError(
					writeJsonSchemaArrayAdditionalItemsAndItemsAndPrefixItemsMessage()
				)
			} else validatedSchema.additionalItems = validatedSchema.items
		}
		validatedSchema.items = validatedSchema.prefixItems
		itemsIsPrefixItems = true
	}

	if ("items" in validatedSchema) {
		if (Array.isArray(validatedSchema.items)) {
			arktypeArraySchema.sequence = {
				prefix: validatedSchema.items.map(item =>
					parseJsonSchema(item, ctx).internal
				)
			}

			if ("additionalItems" in validatedSchema) {
				if (validatedSchema.additionalItems !== false) {
					arktypeArraySchema.sequence = {
						...arktypeArraySchema.sequence,
						variadic: parseJsonSchema(
							validatedSchema.additionalItems,
							ctx
						).internal
					}
				}
			} else if (itemsIsPrefixItems) {
				arktypeArraySchema.sequence = {
					...arktypeArraySchema.sequence,
					variadic: type.unknown.internal
				}
			}
		} else {
			if ("additionalItems" in validatedSchema) {
				throwParseError(
					writeJsonSchemaArrayNonArrayItemsAndAdditionalItemsMessage()
				)
			}
			arktypeArraySchema.sequence = {
				variadic: parseJsonSchema(validatedSchema.items, ctx).internal
			}
		}
	} else if ("additionalItems" in validatedSchema) {
		arktypeArraySchema.sequence = {
			variadic: parseJsonSchema(validatedSchema.additionalItems, ctx).internal
		}
	}

	if ("maxItems" in validatedSchema)
		arktypeArraySchema.maxLength = validatedSchema.maxItems
	if ("minItems" in validatedSchema)
		arktypeArraySchema.minLength = validatedSchema.minItems

	const predicates: Predicate.Schema[] = []
	if ("uniqueItems" in validatedSchema && validatedSchema.uniqueItems === true)
		predicates.push(jsonSchemaArrayUniqueItemsValidator)

	if ("contains" in validatedSchema) {
		const parsedContainsJsonSchema = parseJsonSchema(
			validatedSchema.contains,
			ctx
		)
		predicates.push(arrayContainsItemMatchingSchema(parsedContainsJsonSchema))
	}

	if (predicates.length > 0) arktypeArraySchema.predicate = predicates

	return rootSchema(arktypeArraySchema) as never
}
