const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
]

const hasObjectKeywords = (jsonSchema: object): boolean =>
	objectKeywords.some(key => key in jsonSchema)

const numberKeywords = [
	"minimum",
	"maximum",
	"exclusiveMinimum",
	"exclusiveMaximum",
	"multipleOf"
]

const stringKeywords = ["minLength", "maxLength", "pattern"]

const arrayKeywords = [
	"items",
	"prefixItems",
	"additionalItems",
	"contains",
	"uniqueItems",
	"minItems",
	"maxItems"
